1	// Command govflow is the DAO 治理提案与执行平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"errors"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11		"strings"
12	
13		"github.com/gzhysuiioo/govflow-proposals/govflow"
14		"github.com/gzhysuiioo/govflow-proposals/govflow/batchreg"
15	)
16	
17	const batchRegisterUsage = `usage: govflow batch-register --registry FILE --batch ID --product ID --quantity N --unit UNIT
18	run 'govflow help' for the full description and the registry file format.
19	`
20	
21	const batchImportUsage = `usage: govflow batch-import --registry FILE --input FILE
22	run 'govflow help' for the full description and the registry file format.
23	`
24	
25	func main() {
26		if err := run(os.Args[1:]); err != nil {
27			fmt.Fprintln(os.Stderr, "govflow:", err)
28			var ue *usageError
29			if errors.As(err, &ue) {
30				fmt.Fprint(os.Stderr, ue.usage)
31			}
32			os.Exit(1)
33		}
34	}
35	
36	type usageError struct {
37		msg   string
38		usage string
39	}
40	
41	func (e *usageError) Error() string { return e.msg }
42	
43	func run(args []string) error {
44		command := "demo"
45		if len(args) > 0 {
46			command = args[0]
47		}
48		switch command {
49		case "demo":
50			runDemo()
51			return nil
52		case "version":
53			fmt.Println("govflow 0.1.0")
54			return nil
55		case "help", "-h", "--help":
56			fmt.Print(rootUsage())
57			return nil
58		case "batch-register":
59			return runBatchRegister(args[1:], os.Stdout)
60		case "batch-import":
61			return runBatchImport(args[1:], os.Stdout)
62		default:
63			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
64			fmt.Fprint(os.Stderr, rootUsage())
65			os.Exit(2)
66			return nil
67		}
68	}
69	
70	func rootUsage() string {
71		return `govflow - DAO 治理提案与执行平台 / supply-chain batch registry
72	
73	usage:
74	  govflow                                  run the built-in demo (default)
75	  govflow demo                             run the built-in demo
76	  govflow version                          print the version
77	  govflow help                             show this help
78	  govflow batch-register --registry FILE \
79	      --batch ID --product ID --quantity N --unit UNIT
80	                                           register one supply-chain batch in
81	                                           the registry FILE (see below)
82	  govflow batch-import --registry FILE --input FILE
83	                                           register every batch listed in the
84	                                           JSON manifest FILE into the registry
85	                                           FILE, all records or none
86	
87	batch-register flags:
88	  --registry FILE   registry file to read and write (required)
89	  --batch ID        batch number; unique within one registry file (required)
90	  --product ID      product number the batch belongs to (required)
91	  --quantity N      positive decimal integer, digits 0-9 only, leading
92	                    zeros allowed, max 9223372036854775807 (required)
93	  --unit UNIT       measurement unit, e.g. kg or box (required)
94	
95	batch-import flags:
96	  --registry FILE   registry file to read and write (required)
97	  --input FILE      read-only JSON manifest (required); a non-empty array of
98	                    objects carrying exactly batch, product, quantity and
99	                    unit. Text fields must be non-blank after trimming, and
100	                    quantity must be a JSON integer from 1 to
101	                    9223372036854775807 (no strings, fractions or exponents)
102	
103	The whole manifest is rejected unless every record can be registered or
104	confirmed as a duplicate: a batch id already stored or seen earlier in the
105	manifest must match product, quantity and unit exactly, or none of the new
106	batches are saved and the error names the 1-based record position, the batch
107	id and the mismatching field(s). On success stdout contains one JSON object
108	whose results array keeps manifest order, each entry carrying the normalized
109	four fields plus status "created" or "duplicate"; new batches are appended
110	in first-occurrence order and an all-duplicate manifest leaves the registry
111	file byte-for-byte untouched.
112	
113	Batch, product and unit values have leading and trailing whitespace removed
114	and must be non-empty afterwards; interior characters and casing are kept
115	("B1" and "b1" are different batches). One invocation registers one batch.
116	
117	Batch, product and unit must be valid UTF-8 text in every source: command
118	line flags, import manifest records and stored registry records. A value
119	containing malformed UTF-8 bytes (or a JSON string holding a lone surrogate
120	escape such as "\ud800") is rejected and never replaced with the U+FFFD
121	replacement character, so distinct inputs cannot collapse onto one batch
122	id; the error names the parameter, or the manifest/registry file with the
123	1-based record position and field (plus the batch id only when it is itself
124	valid and unambiguous). A genuinely entered U+FFFD character is ordinary
125	text, non-ASCII ids (Chinese text, emoji, ...) are welcome, and a JSON
126	escape means the same text as the character written directly.
127	
128	On success stdout contains a single JSON object, e.g.
129	  {"batch":"B-001","product":"P-7","quantity":120,"unit":"kg","status":"created"}
130	status is "created" for a new record and "duplicate" when the same batch was
131	already registered with the identical product, quantity and unit; a duplicate
132	does not rewrite the file and is safe to retry. Registering an existing batch
133	with any different field is rejected; the error names the batch and the
134	mismatching field(s) and no record is changed.
135	
136	registry file format (UTF-8 JSON, human-inspectable):
137	  {
138	    "version": 1,
139	    "batches": [
140	      {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
141	    ]
142	  }
143	A missing file is created on first registration. An existing file that is
144	empty, cannot be read in this format, or contains several records with the
145	same batch number is rejected outright and never overwritten. "This format"
146	is strict: the root object must carry exactly version (the integer 1) and
147	batches (an array, empty allowed), each record exactly the four lowercase
148	fields batch, product, quantity and unit; missing, null, mistyped, unknown
149	or case-variant fields (Version, Batch, ...) are rejected, and so is any
150	field appearing twice in one object — even with identical values, even when
151	one spelling hides behind a JSON escape. The error names the file, the
152	field and the reason, plus the 1-based record position (and the batch id
153	when it is unambiguous) for record-level problems. Failures print
154	the reason to stderr and exit non-zero without touching the registry.
155	`
156	}
157	
158	func runBatchRegister(args []string, stdout io.Writer) error {
159		fs := flag.NewFlagSet("batch-register", flag.ContinueOnError)
160		fs.SetOutput(io.Discard)
161		registryPath := fs.String("registry", "", "registry `file` to read and write")
162		batchRaw := fs.String("batch", "", "batch number (unique within the registry)")
163		productRaw := fs.String("product", "", "product number")
164		quantityRaw := fs.String("quantity", "", "positive decimal integer quantity")
165		unitRaw := fs.String("unit", "", "measurement unit")
166		if err := fs.Parse(args); err != nil {
167			if errors.Is(err, flag.ErrHelp) {
168				fmt.Fprint(stdout, rootUsage())
169				return nil
170			}
171			return &usageError{msg: "batch-register: " + err.Error(), usage: batchRegisterUsage}
172		}
173		if fs.NArg() != 0 {
174			return &usageError{
175				msg:   fmt.Sprintf("batch-register: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
176				usage: batchRegisterUsage,
177			}
178		}
179	
180		// Missing or malformed input must never create or modify the registry
181		// file, so required flags are checked before reading or writing anything.
182		required := []struct {
183			name  string
184			value string
185		}{
186			{"--registry", *registryPath},
187			{"--batch", *batchRaw},
188			{"--product", *productRaw},
189			{"--quantity", *quantityRaw},
190			{"--unit", *unitRaw},
191		}
192		var missing []string
193		for _, f := range required {
194			if f.value == "" {
195				missing = append(missing, f.name)
196			}
197		}
198		if len(missing) > 0 {
199			return &usageError{
200				msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
201				usage: batchRegisterUsage,
202			}
203		}
204	
205		batch, err := batchreg.NormalizeField(*batchRaw)
206		if err != nil {
207			return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
208		}
209		product, err := batchreg.NormalizeField(*productRaw)
210		if err != nil {
211			return &usageError{msg: "batch-register: invalid --product: " + err.Error(), usage: batchRegisterUsage}
212		}
213		unit, err := batchreg.NormalizeField(*unitRaw)
214		if err != nil {
215			return &usageError{msg: "batch-register: invalid --unit: " + err.Error(), usage: batchRegisterUsage}
216		}
217		quantity, err := batchreg.ParseQuantity(*quantityRaw)
218		if err != nil {
219			return &usageError{msg: "batch-register: invalid --quantity: " + err.Error(), usage: batchRegisterUsage}
220		}
221	
222		reg, existed, err := batchreg.Load(*registryPath)
223		if err != nil {
224			return err
225		}
226		outcome, err := batchreg.Register(reg, batchreg.Input{
227			Batch: batch, Product: product, Quantity: quantity, Unit: unit,
228		})
229		if err != nil {
230			return err
231		}
232		if outcome.Created {
233			if err := batchreg.Save(*registryPath, reg); err != nil {
234				if !existed {
235					// Nothing was registered before; drop any partial new file.
236					os.Remove(*registryPath)
237				}
238				return err
239			}
240		}
241	
242		status := "duplicate"
243		if outcome.Created {
244			status = "created"
245		}
246		result := struct {
247			Batch    string `json:"batch"`
248			Product  string `json:"product"`
249			Quantity int64  `json:"quantity"`
250			Unit     string `json:"unit"`
251			Status   string `json:"status"`
252		}{
253			Batch:    outcome.Batch.Batch,
254			Product:  outcome.Batch.Product,
255			Quantity: outcome.Batch.Quantity,
256			Unit:     outcome.Batch.Unit,
257			Status:   status,
258		}
259		payload, err := json.Marshal(result)
260		if err != nil {
261			return err
262		}
263		_, err = fmt.Fprintln(stdout, string(payload))
264		return err
265	}
266	
267	func runBatchImport(args []string, stdout io.Writer) error {
268		fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
269		fs.SetOutput(io.Discard)
270		registryPath := fs.String("registry", "", "registry `file` to read and write")
271		inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
272		if err := fs.Parse(args); err != nil {
273			if errors.Is(err, flag.ErrHelp) {
274				fmt.Fprint(stdout, rootUsage())
275				return nil
276			}
277			return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
278		}
279		if fs.NArg() != 0 {
280			return &usageError{
281				msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
282				usage: batchImportUsage,
283			}
284		}
285		if *registryPath == "" || *inputPath == "" {
286			var missing []string
287			if *registryPath == "" {
288				missing = append(missing, "--registry")
289			}
290			if *inputPath == "" {
291				missing = append(missing, "--input")
292			}
293			return &usageError{
294				msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
295				usage: batchImportUsage,
296			}
297		}
298	
299		// The manifest is read-only and is parsed (and fully validated) before
300		// the registry is loaded or written, so bad input cannot touch it.
301		data, err := os.ReadFile(*inputPath)
302		if err != nil {
303			return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
304		}
305		inputs, err := batchreg.ParseManifest(data)
306		if err != nil {
307			return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
308		}
309	
310		reg, existed, err := batchreg.Load(*registryPath)
311		if err != nil {
312			return fmt.Errorf("batch-import: %w", err)
313		}
314		outcomes, err := batchreg.Import(reg, inputs)
315		if err != nil {
316			return fmt.Errorf("batch-import: %w", err)
317		}
318	
319		type importResultJSON struct {
320			Batch    string `json:"batch"`
321			Product  string `json:"product"`
322			Quantity int64  `json:"quantity"`
323			Unit     string `json:"unit"`
324			Status   string `json:"status"`
325		}
326		results := make([]importResultJSON, len(outcomes))
327		anyCreated := false
328		for i, o := range outcomes {
329			status := "duplicate"
330			if o.Created {
331				status = "created"
332				anyCreated = true
333			}
334			results[i] = importResultJSON{
335				Batch:    o.Batch.Batch,
336				Product:  o.Batch.Product,
337				Quantity: o.Batch.Quantity,
338				Unit:     o.Batch.Unit,
339				Status:   status,
340			}
341		}
342	
343		// An all-duplicate manifest must leave bytes and mtime untouched, so the
344		// registry is written only when at least one record was newly created.
345		if anyCreated {
346			if err := batchreg.Save(*registryPath, reg); err != nil {
347				if !existed {
348					// The registry never existed before this import; drop any
349					// partial new file so a failed save leaves nothing behind.
350					os.Remove(*registryPath)
351				}
352				return fmt.Errorf("batch-import: %w", err)
353			}
354		}
355	
356		payload, err := json.Marshal(struct {
357			Results []importResultJSON `json:"results"`
358		}{Results: results})
359		if err != nil {
360			return fmt.Errorf("batch-import: %w", err)
361		}
362		_, err = fmt.Fprintln(stdout, string(payload))
363		if err != nil {
364			return fmt.Errorf("batch-import: %w", err)
365		}
366		return nil
367	}
368	
369	func runDemo() {
370		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
371			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
372		if err := govflow.Vote(&proposal, 700, true); err != nil {
373			fmt.Println("vote refused:", err)
374		}
375		if err := govflow.Vote(&proposal, 200, false); err != nil {
376			fmt.Println("vote refused:", err)
377		}
378		next := govflow.Tally(&proposal)
379		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
380		proposal.State = next
381		proposal.TimelockEnd = 400
382		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
383	}
