	// as a U+FFFD substitution either.
	badByte := []byte(`[{"batch":"B`)
	badByte = append(badByte, 0xff)
	badByte = append(badByte, []byte(`","product":"P","quantity":1,"unit":"kg","supplier":1}]`)...)
